SYSTEMTIME systemAt(double s){ULARGE_INTEGER x;x.QuadPart=(ULONGLONG)((s+11644473600.0)*10000000.0);FILETIME ft={x.LowPart,x.HighPart};SYSTEMTIME st{};FileTimeToSystemTime(&ft,&st);return st;}
