std::wstring windowsZone(std::string zone){static const std::map<std::string,std::string> aliases={{"Europe/Kyiv","Europe/Kiev"},{"Asia/Kolkata","Asia/Calcutta"},{"Asia/Kathmandu","Asia/Katmandu"},{"Asia/Yangon","Asia/Rangoon"},{"America/Nuuk","America/Godthab"}};auto a=aliases.find(zone);if(a!=aliases.end())zone=a->second;if(zone=="UTC"||zone=="Etc/UTC"||zone=="Etc/GMT")return L"UTC";auto it=ZONE_MAP.find(zone);return it==ZONE_MAP.end()?L"":it->second;}
