json normalized(json s){
if(!s.is_object()||!zoneSupported(str(s,"zone")))throw std::runtime_error("Unsupported time zone");
auto show=defaultShow();if(s.contains("show")&&s["show"].is_object())for(auto k:SHOW_KEYS)show[k]=flag(s["show"],k,show[k].get<bool>());s["show"]=show;
s["name"]=str(s,"name",str(s,"zone"));s["region"]=str(s,"region");s["x"]=(int)number(s,"x",80);s["y"]=(int)number(s,"y",50);s["top"]=flag(s,"top",true);s["glass"]=flag(s,"glass",true);s["theme"]=str(s,"theme",flag(s,"dark")?"dark":"system");s["color_mode"]=str(s,"color_mode","system");s["color"]=str(s,"color","#d7d8d8");if(!flag(s,"opacity_direction")){s["transparency"]=100-number(s,"transparency",std::round((255-number(s,"alpha",210))*100/255));s["opacity_direction"]=true;}s["transparency"]=std::clamp((int)number(s,"transparency",std::round((255-number(s,"alpha",210))*100/255)),0,100);
for(auto p:presets())if(str(p,"zone")==str(s,"zone")&&!s.contains("lat")){s["lat"]=p["lat"];s["lon"]=p["lon"];if(str(s,"region").empty())s["region"]=p["region"];}
if(s.contains("lat")&&(!s["lat"].is_number()||!s.contains("lon")||!s["lon"].is_number()||std::abs(number(s,"lat"))>90||std::abs(number(s,"lon"))>180)){s.erase("lat");s.erase("lon");}return s;}
