struct Sun{int day=-1;double rise=0,set=0;};
Sun sunFor(const json& w,const std::string& zone,double now){Sun s;auto today=dateOf(localAt(zone,now));if(w.contains("days")&&w["days"].is_array())for(const auto& row:w["days"]){if(str(row,"date")==today){s.rise=number(row,"rise");s.set=number(row,"set");if(s.rise>0&&s.set>s.rise){s.day=now>=s.rise&&now<s.set?1:0;return s;}}}if(std::abs(now-number(w,"current_time"))<=1800&&w.contains("is_day")&&w["is_day"].is_number())s.day=(int)number(w,"is_day",-1);return s;}
