bool setAutoStart(bool on){HKEY key;auto r=RegCreateKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,nullptr,0,KEY_SET_VALUE,nullptr,&key,nullptr);if(r!=ERROR_SUCCESS)return false;if(on){auto command=L"\""+executable()+L"\" --startup";r=RegSetValueExW(key,L"WorldClockPython",0,REG_SZ,(const BYTE*)command.c_str(),(DWORD)((command.size()+1)*sizeof(wchar_t)));}else{r=RegDeleteValueW(key,L"WorldClockPython");if(r==ERROR_FILE_NOT_FOUND)r=ERROR_SUCCESS;}RegCloseKey(key);return r==ERROR_SUCCESS;}
