void load(){try{if(fs::exists(g_config)){std::ifstream in(g_config);auto data=json::parse(in);auto rows=data.is_array()?data:data.value("cards",json::array());if(rows.is_array())for(auto s:rows){if(g_cards.size()>=30)break;try{if(data.is_array())s["top"]=true;addCard(s);}catch(...){}}}}catch(...){std::error_code ec;auto backup=g_config;backup+=L".unreadable-backup";fs::copy_file(g_config,backup,fs::copy_options::overwrite_existing,ec);}if(g_cards.empty()){auto p=presets();for(int i=0;i<3;i++){p[i]["x"]=160+i*280;p[i]["y"]=50;addCard(p[i]);}}}
