ComPtr<IWICImagingFactory> g_wic;
void resetGraphics(Card* c){c->brush.Reset();c->blur.Reset();c->bitmap.Reset();c->target.Reset();c->captureAt=0;}
HRESULT initGraphics(Card* c){
    RECT r;GetClientRect(c->hwnd,&r);HRESULT hr=g_wic->CreateBitmap(std::max(1L,r.right),std::max(1L,r.bottom),GUID_WICPixelFormat32bppPBGRA,WICBitmapCacheOnLoad,&c->bitmap);if(FAILED(hr))return hr;
    auto props=D2D1::RenderTargetProperties(D2D1_RENDER_TARGET_TYPE_SOFTWARE,D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM,D2D1_ALPHA_MODE_PREMULTIPLIED),c->dpi,c->dpi);
    hr=g_d2d->CreateWicBitmapRenderTarget(c->bitmap.Get(),props,&c->target);if(FAILED(hr))return hr;
    c->target->SetAntialiasMode(D2D1_ANTIALIAS_MODE_PER_PRIMITIVE);c->target->SetTextAntialiasMode(D2D1_TEXT_ANTIALIAS_MODE_GRAYSCALE);
    return c->target->CreateSolidColorBrush(D2D1::ColorF(0x000000),&c->brush);
}
void captureBackground(Card* c){
    RECT r;GetWindowRect(c->hwnd,&r);if(c->blur&&EqualRect(&r,&c->capturedRect)&&nowSeconds()-c->captureAt<1)return;
    int width=r.right-r.left,height=r.bottom-r.top;if(width<=0||height<=0)return;
    HDC screen=GetDC(nullptr);if(!screen){c->error=L"GetDC: "+std::to_wstring(GetLastError());return;}HDC dc=CreateCompatibleDC(screen);HBITMAP image=CreateCompatibleBitmap(screen,width,height);
    if(!dc||!image){if(image)DeleteObject(image);if(dc)DeleteDC(dc);ReleaseDC(nullptr,screen);return;}
    auto old=SelectObject(dc,image);
    // Deliberately omit CAPTUREBLT: exclude layered clocks, with no hide/move/opacity toggling.
    BOOL ok=BitBlt(dc,0,0,width,height,screen,r.left,r.top,SRCCOPY);c->captureError=ok?0:GetLastError();
    // The isolated test desktop may deny screen reads. Exercise the same blur path
    // with a deterministic fixture, recording separately that live capture was unavailable.
    bool fixture=g_testing&&!ok;
    if(fixture){RECT all{0,0,width,height};FillRect(dc,&all,(HBRUSH)GetStockObject(WHITE_BRUSH));for(int y=0;y<height;y+=16)for(int x=0;x<width;x+=16)if((x/16+y/16)%2){RECT cell{x,y,std::min(x+16,width),std::min(y+16,height)};FillRect(dc,&cell,(HBRUSH)GetStockObject(BLACK_BRUSH));}}

    SelectObject(dc,old);DeleteDC(dc);ReleaseDC(nullptr,screen);
    ComPtr<IWICBitmap> raw;HRESULT hr=(ok||fixture)?g_wic->CreateBitmapFromHBITMAP(image,nullptr,WICBitmapIgnoreAlpha,&raw):E_FAIL;
    DeleteObject(image);ComPtr<IWICBitmapScaler> downsample;ComPtr<ID2D1Bitmap> blurred;
    if(SUCCEEDED(hr))hr=g_wic->CreateBitmapScaler(&downsample);
    if(SUCCEEDED(hr))hr=downsample->Initialize(raw.Get(),std::max(2,width/14),std::max(2,height/14),WICBitmapInterpolationModeFant);
    ComPtr<IWICFormatConverter> converted;
    if(SUCCEEDED(hr))hr=g_wic->CreateFormatConverter(&converted);
    if(SUCCEEDED(hr))hr=converted->Initialize(downsample.Get(),GUID_WICPixelFormat32bppPBGRA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom);
    if(SUCCEEDED(hr))hr=c->target->CreateBitmapFromWicBitmap(converted.Get(),nullptr,&blurred);
    if(SUCCEEDED(hr)){c->blur=blurred;c->capturedRect=r;c->captureAt=nowSeconds();c->captureOK=ok!=FALSE;c->testBlurFixture=fixture;}
}
HRESULT presentLayered(Card* c){
    UINT w,h;c->bitmap->GetSize(&w,&h);std::vector<BYTE> bytes((size_t)w*h*4);HRESULT hr=c->bitmap->CopyPixels(nullptr,w*4,(UINT)bytes.size(),bytes.data());if(FAILED(hr))return hr;
    if(g_testing){c->testCornerAlpha=bytes[3];c->testBackgroundAlpha=bytes[((h-5)*w+w/2)*4+3];c->testMaxAlpha=0;c->testSoftEdges=0;
        for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++){int alpha=bytes[(y*w+x)*4+3];c->testMaxAlpha=std::max(c->testMaxAlpha,alpha);if(x<12&&y<12&&alpha>0&&alpha<255)c->testSoftEdges++;}}
    BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=w;info.bmiHeader.biHeight=-(LONG)h;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;
    HDC dc=CreateCompatibleDC(nullptr);void* pixels=nullptr;HBITMAP dib=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&pixels,nullptr,0);
    if(!dc||!dib){if(dib)DeleteObject(dib);if(dc)DeleteDC(dc);return E_FAIL;}memcpy(pixels,bytes.data(),bytes.size());
    auto old=SelectObject(dc,dib);RECT r;GetWindowRect(c->hwnd,&r);POINT destination{r.left,r.top},source{};SIZE size{(LONG)w,(LONG)h};BLENDFUNCTION blend{AC_SRC_OVER,0,255,AC_SRC_ALPHA};
    BOOL ok=UpdateLayeredWindow(c->hwnd,nullptr,&destination,&size,dc,&source,0,&blend,ULW_ALPHA);
    SelectObject(dc,old);DeleteObject(dib);DeleteDC(dc);return ok?S_OK:E_FAIL;
}
void drawBackdrop(Card* c){
    auto rt=c->target.Get();auto bg=background(c);if(bg.a<=0)return;
    ComPtr<ID2D1RoundedRectangleGeometry> shape;g_d2d->CreateRoundedRectangleGeometry(D2D1::RoundedRect(D2D1::RectF(0,0,260,(float)c->height()),14,14),&shape);
    ComPtr<ID2D1Layer> layer;rt->CreateLayer(nullptr,&layer);
    // One layer opacity multiplies blur, tint, highlight and edge coverage together.
    rt->PushLayer(D2D1::LayerParameters(D2D1::InfiniteRect(),shape.Get(),D2D1_ANTIALIAS_MODE_PER_PRIMITIVE,D2D1::IdentityMatrix(),bg.a),layer.Get());
    c->brush->SetColor(D2D1::ColorF(bg.r,bg.g,bg.b,1));rt->FillRectangle(D2D1::RectF(0,0,260,(float)c->height()),c->brush.Get());
    if(flag(c->state,"glass",true)&&c->blur){rt->DrawBitmap(c->blur.Get(),D2D1::RectF(0,0,260,(float)c->height()),1,D2D1_BITMAP_INTERPOLATION_MODE_LINEAR);c->brush->SetColor(D2D1::ColorF(bg.r,bg.g,bg.b,.40f));rt->FillRectangle(D2D1::RectF(0,0,260,(float)c->height()),c->brush.Get());}
    D2D1_GRADIENT_STOP stops[]={{0,D2D1::ColorF(0xffffff,.20f)},{.5f,D2D1::ColorF(0xffffff,.03f)},{1,D2D1::ColorF(0xffffff,0)}};
    ComPtr<ID2D1GradientStopCollection> collection;ComPtr<ID2D1LinearGradientBrush> shine;
    if(SUCCEEDED(rt->CreateGradientStopCollection(stops,3,&collection))&&SUCCEEDED(rt->CreateLinearGradientBrush(D2D1::LinearGradientBrushProperties(D2D1::Point2F(0,0),D2D1::Point2F(0,(float)c->height())),collection.Get(),&shine)))rt->FillRectangle(D2D1::RectF(0,0,260,(float)c->height()),shine.Get());
    rt->PopLayer();
}
